"""Offline, escaped HTML intelligence report. No scripts or automatic artifact downloads."""
from html import escape
from datetime import datetime,timezone

def html_report(scan):
 e=lambda value:escape(str('' if value is None else value))
 a=scan.get('ai_explanation',{});stages=scan.get('pipeline',{}).get('stages',{})
 css='''body{margin:0;background:#f6f7f2;color:#252b22;font:15px/1.65 system-ui,sans-serif}main{max-width:1040px;margin:40px auto;padding:0 24px}header{margin-bottom:28px}h1{font-size:30px;letter-spacing:-1px;margin:8px 0}h2{font-size:21px;margin:0 0 14px}h3{font-size:15px;margin:0 0 8px}.eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:2px;color:#6a7d3e}.muted{color:#68715e;font-size:13px}.brief,article{background:white;border:1px solid #e5e7dd;border-radius:10px;padding:24px;margin-bottom:20px}.brief{border-top:3px solid #6a7d3e}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.number{font-size:30px;font-weight:650;line-height:1.2}.status{display:inline-block;background:#edf1e2;padding:3px 9px;border-radius:4px;font-size:12px;margin-right:8px}ul{padding-left:20px}li{margin:8px 0}code{font-size:12px;overflow-wrap:anywhere}details{border-top:1px solid #e5e7dd;padding:16px 0}summary{cursor:pointer;font-weight:600}p{overflow-wrap:anywhere}footer{margin:30px 0;color:#68715e;font-size:12px}@media(max-width:650px){.grid{grid-template-columns:1fr}main{padding:0 16px;margin:20px auto}.brief,article{padding:18px}}@media print{body{background:white}main{margin:0;max-width:none}article,.brief{break-inside:avoid}}'''
 def listing(title,values):return '<h3>'+e(title)+'</h3><ul>'+''.join('<li>'+e(x)+'</li>' for x in values)+'</ul>' if values else ''
 sources=''.join('<p><strong>'+e(name.title())+'</strong> <span class="status">'+e(stage.get('status'))+'</span><br><span class="muted">'+e(stage.get('detail'))+'</span></p>' for name,stage in stages.items())
 cards=[]
 for provider in ('virustotal','urlhaus'):
  row=next((x for x in scan.get('reputation',{}).get('results',[]) if x.get('provider')==provider),{})
  name='VirusTotal' if provider=='virustotal' else 'URLhaus';stats=row.get('stats',{})
  body='<p>'+e(row.get('status','Not queried'))+'</p>'
  if provider=='virustotal' and row.get('status')=='FOUND':
   flagged=stats.get('malicious',0)+stats.get('suspicious',0);total=flagged+stats.get('undetected',0)+stats.get('harmless',0)
   body='<p class="number">'+e(flagged)+' / '+e(total)+'</p><p>Flagged / existing engine verdicts</p><p class="muted">'+e(stats.get('type-unsupported',0))+' unsupported. Lookup of an existing report; no fresh VirusTotal APK scan was submitted.</p>'
  elif row.get('status')=='NOT_FOUND':body+='<p>No matching SHA-256 record. Reputation remains unknown.</p>'
  elif row.get('detail'):body+='<p>'+e(row['detail'])+'</p>'
  cards.append('<article><h2>'+name+'</h2>'+body+'<p class="muted">SHA-256 lookup only · no APK upload</p></article>')
 findings=''.join('<details><summary>'+e(f.get('id'))+' · '+e(f.get('title'))+'</summary><p>'+e(f.get('description'))+'</p><p class="muted">'+e(f.get('severity'))+' severity · '+e(f.get('confidence'))+' confidence · '+e(f.get('evidence_source','STATIC'))+'</p></details>' for f in scan.get('findings',[]))
 runtime=''.join('<p><strong>'+e(r.get('provider'))+' · '+e(r.get('status'))+'</strong><br>'+e(r.get('device',{}).get('model','Device unavailable'))+' · Android '+e(r.get('device',{}).get('version',r.get('device',{}).get('android_version','unknown')))+' · '+e('NOT_RUN' if r.get('status')=='NOT_RUN' else r.get('coverage','LIMITED'))+' coverage</p>'+listing('Analysis gaps',r.get('analysis_gaps',[])) for r in scan.get('dynamic_results',{}).values()) or '<p>No verified runtime execution was available.</p>'
 created=datetime.fromtimestamp(scan.get('created',0),timezone.utc).strftime('%Y-%m-%d %H:%M UTC')
 sections=''.join('<article><h2>'+e(x.get('title'))+'</h2><p>'+e(x.get('text'))+'</p><p class="muted">Evidence references: '+e(', '.join(x.get('evidence_ids',[])))+'</p></article>' for x in a.get('sections',[]))
 vt=scan.get('vt_intelligence',{});collection='<article><h2>VirusTotal evidence collection</h2>'+''.join('<p><strong>'+e(g.get('label'))+'</strong> · '+e(g.get('id'))+' · '+e(g.get('status'))+(' · partial retrieval' if g.get('truncated') else '')+'</p>' for g in vt.get('groups',[]))+'</article>' if vt else ''
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>APKTrust intelligence report</title><style>'+css+'</style></head><body><main><header><div class="eyebrow">APKTrust · Investigation intelligence</div><h1>'+e(scan.get('package'))+'</h1><p class="muted">'+e(scan.get('filename'))+' · '+created+' · '+e(scan.get('duration'))+'s '+('total' if scan.get('pipeline') else 'static checks')+'</p><code>SHA-256 '+e(scan.get('sha256'))+'</code></header><section class="brief"><h2>What the evidence says</h2><p>'+e(a.get('summary','A combined hosted intelligence summary is unavailable. Review the collected evidence and gaps below.'))+'</p><p class="muted">'+e('AI interpretation · '+a['provider'] if a.get('provider') and a['provider']!='local' else 'Local evidence overview · hosted AI synthesis unavailable')+'</p>'+listing('Key observations',a.get('highlights',[]))+listing('Recommended next steps',a.get('recommendations',[]))+'<p class="muted">Limited evidence supports review, not an APK safety guarantee.</p></section>'+sections+collection+'<div class="grid">'+''.join(cards)+'</div><div class="grid"><article><h2>Analysis stages</h2>'+sources+'</article><article><h2>Runtime evidence</h2>'+runtime+'</article></div><article><h2>Unresolved questions</h2>'+listing('AI-identified limitations',a.get('uncertainties',[]))+listing('Analyzer limitations',scan.get('limitations',[]))+'<p>Static analysis is bounded. Full decompilation and semantic data flow are not configured; Robo is not a full malware sandbox.</p></article><article><h2>Evidence-backed findings</h2>'+findings+'</article><footer>APKTrust · Missing records and behavior not observed during limited execution do not establish safety. Screenshot contents are not embedded in this HTML report.</footer></main></body></html>'
